  name text not null check (char_length(trim(name)) between 1 and 120),
  supplier text not null default '' check (char_length(supplier) <= 180),
  received_on date not null default current_date,
  notes text not null default '' check (char_length(notes) <= 2000),
  purchase_cost_cents integer check (purchase_cost_cents between 0 and 2000000000),
  status text not null default 'open' check (status in ('open','closed')),
  created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
  revision bigint not null default 0,
  unique (id, empresa_id)
);
create table public.marketplace_price_lot_items (
  id uuid primary key,
  lot_id uuid not null,
  empresa_id uuid not null,
  scanned_code text not null check (char_length(trim(scanned_code)) between 1 and 180),
  quantity integer not null default 1 check (quantity between 1 and 100000),
  history_id uuid references public.marketplace_price_consultations(id) on delete set null,
  product_name text, product_description text, image_url text,
  reference_source text, researched_at timestamptz,
  market_price_cents integer, minimum_price_cents integer, medium_price_cents integer, ideal_price_cents integer,
  created_at timestamptz not null default now(),
  foreign key (lot_id,empresa_id) references public.marketplace_price_lots(id,empresa_id) on delete cascade,
  constraint lot_prices_complete check (
    (market_price_cents is null and minimum_price_cents is null and medium_price_cents is null and ideal_price_cents is null)
    or (market_price_cents is not null and market_price_cents > 0 and minimum_price_cents is not null and minimum_price_cents > 0
      and medium_price_cents is not null and medium_price_cents > 0 and ideal_price_cents is not null and ideal_price_cents > 0))
);
create index marketplace_price_lots_company_idx on public.marketplace_price_lots(empresa_id,created_at desc,id);
create index marketplace_price_lot_items_lot_idx on public.marketplace_price_lot_items(lot_id,empresa_id,created_at,id);
alter table public.marketplace_price_lots enable row level security;
alter table public.marketplace_price_lot_items enable row level security;
revoke all on public.marketplace_price_lots, public.marketplace_price_lot_items from public, anon, authenticated;
grant select,insert,update,delete on public.marketplace_price_lots,public.marketplace_price_lot_items to service_role;

-- Lock comum para fechamento/captura: um lote fechado nunca recebe leituras tardias.
-- O UUID da leitura é a chave idempotente; duas leituras físicas têm UUIDs diferentes.
create function public.marketplace_price_lot_mutate(p_empresa_id uuid,p_lot_id uuid,p_action text,p_data jsonb)
returns void language plpgsql set search_path = public as $
declare l public.marketplace_price_lots; h public.marketplace_price_consultations;
begin
  select * into l from public.marketplace_price_lots where id=p_lot_id and empresa_id=p_empresa_id for update;
  if not found then raise exception 'Lote não encontrado.' using errcode='P0002'; end if;
  if p_action='metadata' then
    update public.marketplace_price_lots set name=p_data->>'name',supplier=p_data->>'supplier',
      received_on=(p_data->>'received_on')::date,notes=p_data->>'notes',
      purchase_cost_cents=(p_data->>'purchase_cost_cents')::integer,updated_at=now(),revision=revision+1 where id=l.id;
  elsif p_action='status' then
    update public.marketplace_price_lots set status=p_data->>'status',updated_at=now(),revision=revision+1 where id=l.id;
  else
    if l.status <> 'open' then raise exception 'Lote concluído. Reabra para alterar os produtos.'; end if;
    if p_action='capture' then
      insert into public.marketplace_price_lot_items(id,lot_id,empresa_id,scanned_code)
        values((p_data->>'item_id')::uuid,l.id,l.empresa_id,p_data->>'scanned_code') on conflict(id) do nothing;
      if not exists(select 1 from public.marketplace_price_lot_items where id=(p_data->>'item_id')::uuid and lot_id=l.id and empresa_id=l.empresa_id and scanned_code=p_data->>'scanned_code')
        then raise exception 'Identificador de leitura já utilizado.'; end if;
    elsif p_action='resolve' then
      select * into h from public.marketplace_price_consultations where id=(p_data->>'history_id')::uuid and empresa_id=l.empresa_id;
      if not found then raise exception 'Consulta não encontrada nesta empresa.' using errcode='P0002'; end if;
      if not exists(select 1 from public.marketplace_price_lot_items where id=(p_data->>'item_id')::uuid and lot_id=l.id and empresa_id=l.empresa_id)
        then raise exception 'Leitura não encontrada.' using errcode='P0002'; end if;
      update public.marketplace_price_lot_items set history_id=h.id,product_name=h.product_name,product_description=h.product_description,
        image_url=h.image_url,reference_source=h.sample_source,researched_at=h.last_researched_at,
        market_price_cents=h.market_price_cents,minimum_price_cents=h.minimum_price_cents,medium_price_cents=h.medium_price_cents,ideal_price_cents=h.ideal_price_cents
        where id=(p_data->>'item_id')::uuid and lot_id=l.id and empresa_id=l.empresa_id and market_price_cents is null;
    elsif p_action='quantity' then
      update public.marketplace_price_lot_items set quantity=(p_data->>'quantity')::integer
        where id=(p_data->>'item_id')::uuid and lot_id=l.id and empresa_id=l.empresa_id;
      if not found then raise exception 'Leitura não encontrada.' using errcode='P0002'; end if;
    elsif p_action='remove' then
      delete from public.marketplace_price_lot_items where id=(p_data->>'item_id')::uuid and lot_id=l.id and empresa_id=l.empresa_id;
    else raise exception 'Ação de lote inválida.'; end if;
    update public.marketplace_price_lots set updated_at=now(),revision=revision+1 where id=l.id;
  end if;
end $;
revoke all on function public.marketplace_price_lot_mutate(uuid,uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.marketplace_price_lot_mutate(uuid,uuid,text,jsonb) to service_role;
commit;
-- Recuperação: manter tabelas/dados e desativar a interface. Não remover lotes em rollback de aplicação.

-- Exclusão: conferir anúncios importados de todas as contas, mesmo sem vínculo.
begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
-- Reutiliza a política existente, sem conceder novos acessos. Compatível com
-- instalações anteriores à liberação dedicada de exclusão no AvantaPreços.
create or replace function public.marketplace_product_removal_discovery_access(p_company uuid,p_actor uuid)
returns boolean language plpgsql security definer set search_path=public as $
declare allowed boolean;
begin
 if to_regprocedure('public.marketplace_product_removal_authorized(uuid,uuid)') is not null then
  execute 'select public.marketplace_product_removal_authorized($1,$2)' into allowed using p_company,p_actor;
  return allowed;
 end if;
 return exists(select 1 from usuarios_empresa u join empresa_modulos m on m.empresa_id=u.empresa_id
  where u.empresa_id=p_company and u.user_id=p_actor and u.status='ativo' and u.perfil in ('gestor_master','administrador','operador_completo')
   and m.modulo_id='marketplaces' and m.ativo and (m.expira_em is null or m.expira_em>now()));
end $;
create or replace function public.marketplace_product_removal_candidates(p_company uuid,p_actor uuid,p_product uuid)
returns jsonb language plpgsql security definer set search_path=public as $
declare p marketplace_products; result jsonb;
begin
 if not marketplace_product_removal_discovery_access(p_company,p_actor) then raise exception 'Sem permissão para excluir produtos neste perfil.';end if;
 select * into p from marketplace_products where empresa_id=p_company and id=p_product and archived_at is null;
 if not found then raise exception 'Produto já excluído ou não encontrado.';end if;
 select coalesce(jsonb_agg(v order by v->>'connection_id',v->>'provider_listing_id'),'[]'::jsonb) into result from (
  select jsonb_build_object('id',coalesce(l.id::text,'unlinked:'||s.connection_id::text||':'||s.provider_listing_id),
   'connection_id',s.connection_id,'provider',s.provider,'provider_listing_id',s.provider_listing_id,
   'title',s.title,'status',s.status,'reported_stock',null,'source_snapshot','{}'::jsonb,'updated_at',s.synced_at,
   'unlinked',l.id is null,'conflict',other_link.product_id is not null,'accountName',coalesce(c.seller_name,c.seller_reference)) v
  from marketplace_listings s join marketplace_connections c on c.id=s.connection_id and c.empresa_id=p_company
  left join marketplace_product_links l on l.empresa_id=p_company and l.connection_id=s.connection_id and l.provider_listing_id=s.provider_listing_id and l.product_id=p.id
  left join marketplace_product_links other_link on other_link.empresa_id=p_company and other_link.connection_id=s.connection_id and other_link.provider_listing_id=s.provider_listing_id and other_link.product_id<>p.id
  where s.empresa_id=p_company and (l.id is not null or (
   nullif(regexp_replace(coalesce(p.ean,''),'[^0-9]','','g'),'') is not null and (
    ltrim(regexp_replace(coalesce(s.snapshot->>'ean',''),'[^0-9]','','g'),'0')=ltrim(regexp_replace(p.ean,'[^0-9]','','g'),'0')
    or exists(select 1 from jsonb_array_elements(case when jsonb_typeof(s.snapshot->'variations')='array' then s.snapshot->'variations' else '[]'::jsonb end) variation
      where ltrim(regexp_replace(coalesce(variation->>'ean',''),'[^0-9]','','g'),'0')=ltrim(regexp_replace(p.ean,'[^0-9]','','g'),'0')))))
  union all
  select to_jsonb(l)||jsonb_build_object('unlinked',false,'conflict',false,'accountName',coalesce(c.seller_name,c.seller_reference))
  from marketplace_product_links l join marketplace_connections c on c.id=l.connection_id and c.empresa_id=p_company
  where l.empresa_id=p_company and l.product_id=p.id and not exists(select 1 from marketplace_listings s where s.empresa_id=p_company and s.connection_id=l.connection_id and s.provider_listing_id=l.provider_listing_id)
 ) candidates;
 return result;
end $;

create or replace function public.marketplace_product_remove_checked(p_company uuid,p_actor uuid,p_product uuid,p_revision bigint,p_mode text,p_confirmation text,p_key uuid,p_proofs jsonb,p_discovery jsonb)
returns jsonb language plpgsql security definer set search_path=public as $
declare candidates jsonb; candidate jsonb; proof jsonb; saved marketplace_product_removals; outcome jsonb;
begin
 if not marketplace_product_removal_discovery_access(p_company,p_actor) then raise exception 'Sem permissão para excluir produtos neste perfil.';end if;
 perform pg_advisory_xact_lock(hashtextextended('price-products:'||p_company::text,0));
 select * into saved from marketplace_product_removals where empresa_id=p_company and request_key=p_key;
 if found then return marketplace_product_remove(p_company,p_actor,p_product,p_revision,p_mode,p_confirmation,p_key,p_proofs);end if;
 perform 1 from marketplace_products where empresa_id=p_company and id=p_product for update;
 perform 1 from marketplace_listings where empresa_id=p_company order by connection_id,provider_listing_id for share;
 candidates:=marketplace_product_removal_candidates(p_company,p_actor,p_product);
 if jsonb_typeof(p_discovery) is distinct from 'array' or jsonb_array_length(p_discovery)<>jsonb_array_length(candidates)
  or (select count(distinct v->>'linkId') from jsonb_array_elements(p_discovery)v)<>jsonb_array_length(candidates) then raise exception 'Os anúncios encontrados mudaram. Confira a exclusão novamente.';end if;
 for candidate in select * from jsonb_array_elements(candidates) loop
  select v into proof from jsonb_array_elements(p_discovery)v where v->>'linkId'=candidate->>'id';
  if (candidate->>'conflict')::boolean then raise exception 'Há anúncio do mesmo EAN vinculado a outro cadastro. Confira o vínculo antes de excluir.';end if;
  if proof is null or proof->>'connectionId' is distinct from candidate->>'connection_id' or proof->>'listingId' is distinct from candidate->>'provider_listing_id'
   or coalesce(proof->>'status','') not in ('deleted','cancelled','canceled','unpublished') or candidate->>'status' is distinct from proof->>'status'
   or nullif(proof->>'error','') is not null or nullif(proof->>'checkedAt','') is null
   or (proof->>'checkedAt')::timestamptz<clock_timestamp()-interval '90 seconds' or (proof->>'checkedAt')::timestamptz>clock_timestamp()+interval '5 seconds'
   then raise exception 'Confirme a exclusão de todos os anúncios encontrados antes de excluir o produto.';end if;
 end loop;
 outcome:=marketplace_product_remove(p_company,p_actor,p_product,p_revision,p_mode,p_confirmation,p_key,p_proofs);
 -- Retém a identidade de TODOS os anúncios conferidos, inclusive os sem vínculo:
 -- a importação posterior já consulta este histórico e não recria o produto.
 update marketplace_product_removals set snapshot=jsonb_set(snapshot,'{product,links}',coalesce(snapshot#>'{product,links}','[]'::jsonb)||coalesce((select jsonb_agg(v) from jsonb_array_elements(candidates)v where (v->>'unlinked')::boolean),'[]'::jsonb),true)||jsonb_build_object('discoveryProofs',p_discovery)
 where empresa_id=p_company and request_key=p_key;
 return outcome;
end $;
revoke all on function public.marketplace_product_removal_discovery_access(uuid,uuid),public.marketplace_product_removal_candidates(uuid,uuid,uuid),public.marketplace_product_remove_checked(uuid,uuid,uuid,bigint,text,text,uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.marketplace_product_removal_candidates(uuid,uuid,uuid),public.marketplace_product_remove_checked(uuid,uuid,uuid,bigint,text,text,uuid,jsonb,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

CREATE OR REPLACE FUNCTION public.marketplace_price_product_register_gallery(p_empresa_id uuid, p_actor_id uuid, p_source_key text, p_data jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid; v_product public.marketplace_products; v_pictures jsonb;
begin
  if jsonb_typeof(p_data->'pictures') is distinct from 'array' or jsonb_array_length(p_data->'pictures')>12 then
    raise exception 'Galeria de fotos inválida.';
  end if;
  if exists(select 1 from jsonb_array_elements(p_data->'pictures') p where jsonb_typeof(p)<>'string' or length(p#>>'{}')>2048 or (p#>>'{}') !~ '^https://[^/@[:space:]]+\.[^/@[:space:]]+(/[^[:space:]]*)?$') then
    raise exception 'Informe fotos com endereços HTTPS válidos.';
  end if;
  v_id:=public.marketplace_price_product_register(p_empresa_id,p_actor_id,p_source_key,p_data);
  select * into v_product from public.marketplace_products where id=v_id and empresa_id=p_empresa_id and archived_at is null for update;
  -- Apenas complementa cadastro sem galeria; nunca remove fotos ou troca capa manual.
  if jsonb_array_length(v_product.pictures)<=1 and nullif(p_data->>'ean','') is not null
    and ltrim(v_product.ean,'0')=ltrim(p_data->>'ean','0')
    and (v_product.pictures='[]'::jsonb or v_product.pictures->>0=p_data->>'image') then
    select coalesce(jsonb_agg(value order by pos),'[]'::jsonb) into v_pictures from (
      select value,min(pos) pos from jsonb_array_elements(v_product.pictures||(p_data->'pictures')) with ordinality a(value,pos)
      group by value order by min(pos) limit 12
    ) gallery;
    if v_pictures<>v_product.pictures then
      update public.marketplace_products set pictures=v_pictures,revision=revision+1,updated_at=now()
        where id=v_id and empresa_id=p_empresa_id;
    end if;
  end if;
  return v_id;
end $function$

CREATE OR REPLACE FUNCTION public.marketplace_product_content_save(p_empresa_id uuid, p_actor_id uuid, p_product_id uuid, p_revision bigint, p_data jsonb, p_request_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_product public.marketplace_products; v_result jsonb; v_values jsonb;
begin
 if jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data) key where key not in ('description','pictures','attributes','category_id')) or (coalesce(p_data->>'category_id','')<>'' and p_data->>'category_id' !~ '^MLB[0-9]+$')
 or jsonb_typeof(p_data->'pictures') is distinct from 'array' or jsonb_array_length(p_data->'pictures')>12
 or jsonb_typeof(p_data->'attributes') is distinct from 'array' or jsonb_array_length(p_data->'attributes')>100
 or jsonb_typeof(p_data->'description') is distinct from 'string' or length(p_data->>'description')>50000 then raise exception 'Ficha inválida.'; end if;
 if exists(select 1 from jsonb_array_elements(p_data->'pictures') p where jsonb_typeof(p)<>'string' or length(p#>>'{}')>2048 or (p#>>'{}') !~ '^https://[^/@[:space:]]+\.[^/@[:space:]]+(/[^[:space:]]*)?$') then raise exception 'Fotos inválidas.'; end if;
 if exists(select 1 from jsonb_array_elements(p_data->'attributes') a where coalesce(a->>'id','') !~ '^[A-Z0-9_]{1,80}$' or length(coalesce(a->>'value',''))>1000 or length(coalesce(a->>'name',''))>120) then raise exception 'Características inválidas.'; end if;
 select * into v_product from public.marketplace_products where id=p_product_id and empresa_id=p_empresa_id and archived_at is null for update;
 if not found or v_product.revision<>p_revision then raise exception 'O cadastro mudou. Recarregue a preparação.'; end if;
 if exists(select 1 from jsonb_array_elements(v_product.pictures) p where not (p_data->'pictures') @> jsonb_build_array(p)) or (v_product.pictures<>'[]'::jsonb and v_product.pictures->>0 is distinct from p_data->'pictures'->>0) then raise exception 'Preserve a capa e as fotos atuais do produto.'; end if;
 v_result:=public.marketplace_product_command(p_empresa_id,p_actor_id,'update',jsonb_build_object('product_id',p_product_id,'revision',p_revision,'name',v_product.name,'ean',v_product.ean,'sku',v_product.sku,'category_id',coalesce(p_data->>'category_id',v_product.category_id),'catalog_product_id',v_product.catalog_product_id,'price_cents',v_product.price_cents,'description',p_data->'description','pictures',p_data->'pictures'),p_request_key);
 select coalesce(jsonb_object_agg(a->>'id',coalesce(nullif(a->>'valueId',''),a->>'value')),'{}') into v_values from jsonb_array_elements(p_data->'attributes') a;
 update public.marketplace_products set attributes=p_data->'attributes',publication_form=publication_form||jsonb_build_object('attributes',v_values) where id=p_product_id and empresa_id=p_empresa_id;
 return v_result;
end $function$

-- Saldo local informado é a referência; importar outro anúncio não reabre conferência.
begin;
set local lock_timeout='5s';
set local statement_timeout='120s';
do $
declare definition text; source_function regprocedure; changed text;
begin
 source_function := (select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and p.proname in ('marketplace_listing_catalog_import','marketplace_listing_catalog_import_before_removal')
 and p.proargtypes='2950 2950 25'::oidvector and position('if canonical is null then' in p.prosrc)>0);
 if source_function is null then raise exception 'Importador original não encontrado; nenhuma regra foi alterada.';end if;
 definition:=pg_get_functiondef(source_function);
 changed:=replace(definition,'if canonical is null then','if canonical is null and exists(select 1 from marketplace_products where empresa_id=p_empresa and id=target and stock_quantity is null) then');
 if changed=definition then raise exception 'Contrato do importador mudou.';end if;
 execute changed;
 definition:=pg_get_functiondef('public.marketplace_import_choose_local(uuid,uuid,uuid,text,uuid,uuid)'::regprocedure);
 changed:=replace(definition,'set listing_stock_review_at=clock_timestamp(),revision=revision+1,updated_at=now() where empresa_id=p_empresa and id=p_product and archived_at is null;',
 'set listing_stock_review_at=case when stock_quantity is null then clock_timestamp() else null end,revision=revision+1,updated_at=now() where empresa_id=p_empresa and id=p_product and archived_at is null;');
 if changed=definition then raise exception 'Contrato da escolha de cadastro mudou.';end if;
 changed:=replace(changed,'and product_id=p_product and state=''pending'';',
 'and product_id=p_product and state=''pending'' and exists(select 1 from marketplace_products where empresa_id=p_empresa and id=p_product and listing_stock_review_at is not null);');
 execute changed;
end $;
-- Remove somente marcadores indevidos de produtos com saldo efetivamente registrado.
-- Não fabrica confirmação física nem movimenta unidades de qualquer depósito.
do $ declare p record;begin
 for p in update public.marketplace_products set listing_stock_review_at=null,revision=revision+1,updated_at=now()
   where archived_at is null and stock_quantity is not null and listing_stock_review_at is not null returning empresa_id,id,stock_confirmed_at
 loop
   if p.stock_confirmed_at is not null then perform public.marketplace_enqueue_stock(p.empresa_id,p.id,false);end if;
 end loop;
end $;
commit;

begin;
set local lock_timeout='5s';
set local statement_timeout='60s';
create table public.marketplace_catalog_completion (
 empresa_id uuid not null references public.empresas(id) on delete cascade, product_id uuid not null,
 actor_id uuid not null, state text not null default 'pending' check(state in ('pending','processing','sending','completed','skipped','failed','review_required')),
 progress jsonb not null default '{}', issue text, lease_owner uuid, lease_until timestamptz,
 next_check_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 primary key(empresa_id,product_id),foreign key(empresa_id,product_id) references public.marketplace_products(empresa_id,id) on delete cascade
);
alter table public.marketplace_catalog_completion enable row level security;
revoke all on public.marketplace_catalog_completion from public,anon,authenticated;
grant select,insert,update on public.marketplace_catalog_completion to service_role;
create index marketplace_catalog_completion_due on public.marketplace_catalog_completion(next_check_at) where state<>'review_required';

create function public.marketplace_catalog_completion_seed(p_company uuid,p_actor uuid)
returns void language plpgsql security definer set search_path=public as $
begin
 if not exists(select 1 from usuarios_empresa u join empresa_modulos m on m.empresa_id=u.empresa_id where u.empresa_id=p_company and u.user_id=p_actor and u.status='ativo' and u.perfil in ('gestor_master','administrador','operador_completo') and m.modulo_id='marketplaces' and m.ativo and (m.expira_em is null or m.expira_em>now())) then raise exception 'Sem permissão para complementar o catálogo.'; end if;
 insert into marketplace_catalog_completion(empresa_id,product_id,actor_id)
 select p_company,p.id,p_actor from marketplace_products p where p.empresa_id=p_company and p.archived_at is null and p.ean is not null
 on conflict(empresa_id,product_id) do update set actor_id=excluded.actor_id where marketplace_catalog_completion.state not in ('processing','sending');
end $;

create function public.marketplace_catalog_completion_claim(p_owner uuid,p_company uuid default null)
returns jsonb language plpgsql security definer set search_path=public as $
declare v_job public.marketplace_catalog_completion;
begin
 if p_owner is null then raise exception 'Tentativa inválida.'; end if;
 perform pg_advisory_xact_lock(hashtextextended('marketplace-catalog-completion',0));
 -- Só retomar automaticamente leituras. Um envio interrompido exige conferência.
 update marketplace_catalog_completion set state=case when state='sending' then 'review_required' else 'pending' end,
 issue=case when state='sending' then 'Envio interrompido: confira os anúncios antes de reenviar.' else issue end,lease_owner=null,lease_until=null
 where state in ('processing','sending') and lease_until<now();
 v_job := (select j from marketplace_catalog_completion j join marketplace_products p on p.empresa_id=j.empresa_id and p.id=j.product_id
 where (p_company is null or j.empresa_id=p_company) and p.archived_at is null and j.state in ('pending','completed','skipped','failed') and j.next_check_at<=now()
 and not exists(select 1 from marketplace_catalog_completion running where running.empresa_id=j.empresa_id and running.state in ('processing','sending') and running.lease_until>now())
 and exists(select 1 from usuarios_empresa u join empresa_modulos m on m.empresa_id=u.empresa_id where u.empresa_id=j.empresa_id and u.user_id=j.actor_id and u.status='ativo' and u.perfil in ('gestor_master','administrador','operador_completo') and m.modulo_id='marketplaces' and m.ativo and (m.expira_em is null or m.expira_em>now()))
 order by j.next_check_at,j.product_id limit 1 for update of j skip locked);
 if v_job.product_id is null then return null; end if;
 update marketplace_catalog_completion set state='processing',lease_owner=p_owner,lease_until=now()+interval '3 minutes',updated_at=now(),progress=case when state='pending' then progress else '{}'::jsonb end where empresa_id=v_job.empresa_id and product_id=v_job.product_id;
 v_job := (select j from marketplace_catalog_completion j where j.empresa_id=v_job.empresa_id and j.product_id=v_job.product_id);
 return to_jsonb(v_job);
end $;

create function public.marketplace_catalog_complete_local(p_company uuid,p_actor uuid,p_product uuid,p_revision bigint,p_owner uuid,p_data jsonb)
returns boolean language plpgsql security definer set search_path=public as $
declare v_product public.marketplace_products; v_pictures jsonb; v_attributes jsonb; v_form jsonb; v_description text; v_entry jsonb; v_old jsonb; v_index integer; v_changed boolean:=false;
begin
 if jsonb_typeof(p_data) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_data) k where k not in ('description','pictures','attributes')) or jsonb_typeof(p_data->'pictures') is distinct from 'array' or jsonb_array_length(p_data->'pictures')>12 or jsonb_typeof(p_data->'attributes') is distinct from 'array' or jsonb_array_length(p_data->'attributes')>100 or jsonb_typeof(p_data->'description') is distinct from 'string' or length(p_data->>'description')>50000 then raise exception 'Complemento inválido.'; end if;
 if not exists(select 1 from usuarios_empresa u join empresa_modulos m on m.empresa_id=u.empresa_id where u.empresa_id=p_company and u.user_id=p_actor and u.status='ativo' and u.perfil in ('gestor_master','administrador','operador_completo') and m.modulo_id='marketplaces' and m.ativo and (m.expira_em is null or m.expira_em>now())) then raise exception 'Sem permissão para complementar.'; end if;
 perform 1 from marketplace_catalog_completion where empresa_id=p_company and product_id=p_product and actor_id=p_actor and lease_owner=p_owner and state='processing' and lease_until>now() for update;
 if not found then raise exception 'A tentativa foi substituída.'; end if;
 v_product := (select p from marketplace_products p where empresa_id=p_company and id=p_product and archived_at is null for update);
 if v_product.id is null or v_product.revision<>p_revision then raise exception 'O cadastro mudou. Os dados preenchidos foram preservados.'; end if;
 v_pictures:=v_product.pictures;v_attributes:=v_product.attributes;v_form:=v_product.publication_form;v_description:=v_product.description;
 if btrim(v_description)='' and btrim(coalesce(v_form->>'description',''))<>'' then v_description:=v_form->>'description';v_changed:=true;
 elsif btrim(v_description)='' and btrim(p_data->>'description')<>'' then v_description:=p_data->>'description';v_changed:=true;end if;
 for v_entry in select * from jsonb_array_elements(p_data->'pictures') loop
  if jsonb_typeof(v_entry)<>'string' or length(v_entry#>>'{}')>2048 or (v_entry#>>'{}') !~ '^https://([a-zA-Z0-9-]+\.)*mlstatic\.com/[^[:space:]]+ then raise exception 'Foto de catálogo inválida.';end if;
  if jsonb_array_length(v_pictures)<12 and not v_pictures @> jsonb_build_array(v_entry) then v_pictures:=v_pictures||jsonb_build_array(v_entry);v_changed:=true;end if;
 end loop;
 for v_entry in select * from jsonb_array_elements(p_data->'attributes') loop
  if coalesce(v_entry->>'id','') !~ '^[A-Z0-9_]{1,80} or length(coalesce(v_entry->>'value','')) not between 1 and 1000 or length(coalesce(v_entry->>'name',''))>120 then raise exception 'Característica inválida.';end if;
  v_index := (select (ord-1)::integer from jsonb_array_elements(v_attributes) with ordinality x(a,ord) where a->>'id'=v_entry->>'id' limit 1);
  v_old := v_attributes->v_index;
  if btrim(coalesce(v_form->'attributes'->>(v_entry->>'id'),''))<>'' then continue;end if;
  if v_index is null then
   if jsonb_array_length(v_attributes)>=100 then continue;end if;
   v_attributes:=v_attributes||jsonb_build_array(v_entry);v_changed:=true;
  elsif btrim(coalesce(v_old->>'value',''))='' and btrim(coalesce(v_old->>'valueId',''))='' then v_attributes:=jsonb_set(v_attributes,array[v_index::text],v_old||v_entry||jsonb_build_object('name',coalesce(nullif(v_old->>'name',''),v_entry->>'name')));v_changed:=true;
  else continue;end if;
  v_form:=jsonb_set(v_form,'{attributes}',coalesce(v_form->'attributes','{}')||jsonb_build_object(v_entry->>'id',coalesce(nullif(v_entry->>'valueId',''),v_entry->>'value')));
 end loop;
 if btrim(coalesce(v_form->>'description',''))='' and v_description<>'' then v_form:=v_form||jsonb_build_object('description',v_description);end if;
 if v_changed then
  update marketplace_products set description=v_description,pictures=v_pictures,attributes=v_attributes,publication_form=v_form,revision=revision+1,updated_at=now() where empresa_id=p_company and id=p_product;
  insert into marketplace_product_operations(empresa_id,request_key,actor_id,action,request_hash,result) values(p_company,p_owner,p_actor,'catalog_complete',md5(p_data::text),jsonb_build_object('product_id',p_product,'catalog_completed',true,'before',to_jsonb(v_product)));
 end if;
 return v_changed;
end $;
revoke all on function public.marketplace_catalog_completion_seed(uuid,uuid),public.marketplace_catalog_completion_claim(uuid,uuid),public.marketplace_catalog_complete_local(uuid,uuid,uuid,bigint,uuid,jsonb) from public,anon,authenticated;
grant execute on function public.marketplace_catalog_completion_seed(uuid,uuid),public.marketplace_catalog_completion_claim(uuid,uuid),public.marketplace_catalog_complete_local(uuid,uuid,uuid,bigint,uuid,jsonb) to service_role;

-- Novos cadastros entram na fila somente em empresas que já ativaram o fluxo.
create function public.marketplace_catalog_completion_new_product()
returns trigger language plpgsql security definer set search_path=public as $
declare v_actor uuid;
begin
 if new.ean is null or new.archived_at is not null then return new;end if;
 if tg_op='UPDATE' and new.ean is not distinct from old.ean then return new;end if;
 v_actor := (select j.actor_id from marketplace_catalog_completion j
 where j.empresa_id=new.empresa_id and exists(select 1 from usuarios_empresa u join empresa_modulos m on m.empresa_id=u.empresa_id where u.empresa_id=j.empresa_id and u.user_id=j.actor_id and u.status='ativo' and u.perfil in ('gestor_master','administrador','operador_completo') and m.modulo_id='marketplaces' and m.ativo and (m.expira_em is null or m.expira_em>now())) order by j.updated_at desc limit 1);
 if v_actor is not null then
  insert into marketplace_catalog_completion(empresa_id,product_id,actor_id) values(new.empresa_id,new.id,v_actor)
  on conflict(empresa_id,product_id) do update set state='pending',progress='{}',issue=null,next_check_at=now() where marketplace_catalog_completion.state not in ('processing','sending','review_required');
 end if;
 return new;
end $;
revoke all on function public.marketplace_catalog_completion_new_product() from public,anon,authenticated;
grant execute on function public.marketplace_catalog_completion_new_product() to service_role;
create trigger marketplace_catalog_completion_on_product after insert or update of ean on public.marketplace_products for each row execute function public.marketplace_catalog_completion_new_product();
commit;

